import csv
import json
from collections import Counter, defaultdict

with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    data = list(reader)

# Normalize country names
def normalize_country(c):
    if not c:
        return "Unknown"
    variants = {
        'China': ['China', 'PR China', "People's Republic of China", 'Peoples Republic of China'],
        'USA': ['USA', 'United States', 'United States of America', 'US'],
        'UK': ['UK', 'United Kingdom', 'England', 'Scotland', 'Wales', 'Northern Ireland'],
        'South Korea': ['Republic of Korea', 'South Korea', 'Korea, Republic of'],
        'Russia': ['Russia', 'Russian Federation'],
        'Iran': ['Iran', 'Iran, Islamic Republic of'],
        'Taiwan': ['Taiwan', 'Taiwan, Province of China'],
    }
    for canonical, aliases in variants.items():
        if c in aliases:
            return canonical
    return c

for r in data:
    r['country_norm'] = normalize_country(r['country'])

# 1. Monthly publication trends (excluding unknown months)
monthly = defaultdict(int)
for r in data:
    if r['pub_month_num'] != '0':
        key = f"{r['pub_year']}-{int(r['pub_month_num']):02d}"
        monthly[key] += 1

sorted_months = sorted(monthly.keys())
print("=== MONTHLY PUBLICATIONS (KNOWN MONTHS) ===")
for m in sorted_months:
    print(f"  {m}: {monthly[m]}")

# 2. OA by month
oa_monthly = defaultdict(lambda: {'True': 0, 'False': 0})
for r in data:
    if r['pub_month_num'] != '0':
        key = f"{r['pub_year']}-{int(r['pub_month_num']):02d}"
        oa_monthly[key][r['open_access']] += 1

print("\n=== OA BY MONTH (KNOWN MONTHS) ===")
for m in sorted_months:
    d = oa_monthly[m]
    total = d['True'] + d['False']
    oa_pct = d['True'] / total * 100 if total > 0 else 0
    print(f"  {m}: OA={d['True']}, Closed={d['False']}, Rate={oa_pct:.1f}%")

# 3. Country by year (top 15)
country_year = defaultdict(lambda: defaultdict(int))
for r in data:
    country_year[r['country_norm']][r['pub_year']] += 1

top15_countries = sorted(country_year.items(), key=lambda x: sum(x[1].values()), reverse=True)[:15]
print("\n=== TOP 15 COUNTRIES BY YEAR ===")
for c, years in top15_countries:
    print(f"  {c}: 2024={years.get('2024',0)}, 2025={years.get('2025',0)}, 2026={years.get('2026',0)}")

# 4. Major topics by year (emerging topics)
topic_year = defaultdict(lambda: defaultdict(int))
for r in data:
    if r['major_topic']:
        topic_year[r['major_topic']][r['pub_year']] += 1

# Topics with meaningful presence, show growth
print("\n=== TOPIC YEAR BREAKDOWN (topics with >=3 total) ===")
topic_totals = {t: sum(y.values()) for t, y in topic_year.items()}
significant_topics = [(t, y) for t, y in topic_year.items() if topic_totals[t] >= 3]
significant_topics.sort(key=lambda x: topic_totals[x[0]], reverse=True)
for t, years in significant_topics[:40]:
    y24 = years.get('2024', 0)
    y25 = years.get('2025', 0)
    y26 = years.get('2026', 0)
    total = y24 + y25 + y26
    print(f"  {t}: 2024={y24}, 2025={y25}, 2026={y26} (total={total})")

# 5. Research type by year
rt_year = defaultdict(lambda: defaultdict(int))
for r in data:
    if r['research_type']:
        for t in r['research_type'].split(';'):
            rt_year[t.strip()][r['pub_year']] += 1

print("\n=== RESEARCH TYPE BY YEAR ===")
for rt in ['Journal Article', 'Review', 'Case Reports', 'Systematic Review', 'Preprint', 'Meta-Analysis', 'Randomized Controlled Trial']:
    y = rt_year.get(rt, {})
    print(f"  {rt}: 2024={y.get('2024',0)}, 2025={y.get('2025',0)}, 2026={y.get('2026',0)}")

# 6. OA by research type
rt_oa = defaultdict(lambda: {'True': 0, 'False': 0})
for r in data:
    if r['research_type']:
        for t in r['research_type'].split(';'):
            rt_oa[t.strip()][r['open_access']] += 1

print("\n=== OA BY RESEARCH TYPE ===")
for rt in ['Journal Article', 'Review', 'Case Reports', 'Systematic Review', 'Preprint', 'Meta-Analysis', 'Randomized Controlled Trial']:
    d = rt_oa.get(rt, {'True': 0, 'False': 0})
    total = d['True'] + d['False']
    if total > 0:
        print(f"  {rt}: OA={d['True']} ({d['True']/total*100:.1f}%), Closed={d['False']}")

# 7. OA by country (top 15)
country_oa = defaultdict(lambda: {'True': 0, 'False': 0})
for r in data:
    country_oa[r['country_norm']][r['open_access']] += 1

print("\n=== OA BY TOP 15 COUNTRIES ===")
for c, _ in top15_countries:
    d = country_oa.get(c, {'True': 0, 'False': 0})
    total = d['True'] + d['False']
    if total > 0:
        print(f"  {c}: OA={d['True']} ({d['True']/total*100:.1f}%), Total={total}")

# 8. Author counts by research type
rt_authors = defaultdict(list)
for r in data:
    if r['research_type'] and r['authors_count']:
        for t in r['research_type'].split(';'):
            rt_authors[t.strip()].append(int(r['authors_count']))

import statistics
print("\n=== MEDIAN AUTHORS BY RESEARCH TYPE ===")
for rt in ['Journal Article', 'Review', 'Case Reports', 'Systematic Review', 'Preprint', 'Meta-Analysis', 'Randomized Controlled Trial']:
    vals = rt_authors.get(rt, [])
    if vals:
        print(f"  {rt}: median={statistics.median(vals):.1f}, mean={statistics.mean(vals):.2f}, n={len(vals)}")

# 9. Topic growth rates (MoM for top emerging topics)
# First, compute monthly topic frequencies for known months
topic_monthly = defaultdict(lambda: defaultdict(int))
for r in data:
    if r['major_topic'] and r['pub_month_num'] != '0':
        key = f"{r['pub_year']}-{int(r['pub_month_num']):02d}"
        topic_monthly[r['major_topic']][key] += 1

# For topics with >10 total, compute growth from first to last appearance
print("\n=== TOPIC TRENDS (topics with >=5 total, known months) ===")
topic_growth = []
for t, months in topic_monthly.items():
    total = sum(months.values())
    if total >= 5:
        sorted_m = sorted(months.keys())
        first = months[sorted_m[0]]
        last = months[sorted_m[-1]]
        if first > 0:
            growth = (last - first) / first * 100
            topic_growth.append((t, total, growth, sorted_m[0], sorted_m[-1], first, last))

topic_growth.sort(key=lambda x: x[2], reverse=True)
for t, total, growth, first_m, last_m, first_c, last_c in topic_growth[:20]:
    print(f"  {t}: {first_c}→{last_c} ({first_m}→{last_m}), growth={growth:.0f}%, total={total}")

# 10. Keywords by year for trending detection
kw_year = defaultdict(lambda: defaultdict(int))
for r in data:
    if r['keywords']:
        for kw in r['keywords'].split(';'):
            kw_year[kw.strip()][r['pub_year']] += 1

# Compare keyword prevalence 2024 vs 2025 (normalized)
n2024 = 3924
n2025 = 737
print("\n=== KEYWORD TRENDS (normalized rate per 1000) ===")
kw_trends = []
for kw, years in kw_year.items():
    y24 = years.get('2024', 0)
    y25 = years.get('2025', 0)
    total = y24 + y25
    if total >= 8:
        rate24 = y24 / n2024 * 1000
        rate25 = y25 / n2025 * 1000
        if rate24 > 0:
            change = (rate25 - rate24) / rate24 * 100
            kw_trends.append((kw, rate24, rate25, change, total))

kw_trends.sort(key=lambda x: x[3], reverse=True)
print("  TOP 15 FASTEST GROWING KEYWORDS:")
for kw, r24, r25, chg, tot in kw_trends[:15]:
    print(f"    {kw}: {r24:.1f}→{r25:.1f}/1000 ({chg:+.0f}%), total={tot}")
print("  TOP 15 FASTEST DECLINING KEYWORDS:")
kw_trends.sort(key=lambda x: x[3])
for kw, r24, r25, chg, tot in kw_trends[:15]:
    print(f"    {kw}: {r24:.1f}→{r25:.1f}/1000 ({chg:+.0f}%), total={tot}")

# 11. Journal OA rates
journal_oa = defaultdict(lambda: {'True': 0, 'False': 0})
for r in data:
    if r['journal']:
        journal_oa[r['journal']][r['open_access']] += 1

print("\n=== TOP JOURNALS WITH OA RATES (top 20 by volume) ===")
journal_totals = {j: sum(d.values()) for j, d in journal_oa.items()}
top_journals = sorted(journal_totals.items(), key=lambda x: x[1], reverse=True)[:20]
for j, tot in top_journals:
    d = journal_oa[j]
    oa_rate = d['True'] / tot * 100
    print(f"  {j[:60]}: {tot} papers, OA={oa_rate:.0f}%")

